WITH unpacked AS (SELECT id, plan, tier_limits, discounts, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, ELEMENT_AT(tier_prices, 1) AS entry_price FROM price_tiers) SELECT CASE WHEN entry_price >= 26 THEN 'LARGE' ELSE 'SMALL' END AS entry_price_tier, plan, PERCENTILE_APPROX(entry_price, ARRAY(0.25, 0.5, 0.75)) AS entry_price_quartiles, SORT_ARRAY(COLLECT_SET(plan)) AS plan_list, PERCENTILE_APPROX(entry_price, 0.9) AS entry_price_p90, ROUND(AVG(entry_price), 2) AS avg_entry_price, MAX(entry_price) FILTER (WHERE plan = 'starter') AS starter_max_entry_price, PERCENTILE_APPROX(entry_price, 0.5) AS entry_price_p50 FROM unpacked GROUP BY entry_price_tier, plan ORDER BY plan;
